const items = $input.all();

return items.map((item, index) => {
  const binaryData = item.binary?.data;
  const filename = String(item.json.fileName || binaryData?.fileName || '');
  const extension = String(
    item.json.fileExtension ||
    binaryData?.fileExtension ||
    filename.split('.').pop() ||
    ''
  ).toLowerCase();

  return {
    json: { ...item.json, filename, extension },
    binary: item.binary,
    pairedItem: { item: index },
  };
});

return $input.all().map((item) => {
  const value = item.json.text;
  const text = Array.isArray(value) ? value.join('\n') : String(value ?? '');

  return {
    json: {
      filename: String(item.json.filename || item.json.fileName || ''),
      extension: 'pdf',
      text: text.trim(),
    },
  };
});

const parsedItems = $input.all();
const sourceItems = $('Extract XML to Text').all();

function collectReadableValues(value, output) {
  if (value === null || value === undefined) return;

  if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
    const text = String(value).replace(/\s+/g, ' ').trim();
    if (text) output.push(text);
    return;
  }

  if (Array.isArray(value)) {
    for (const entry of value) collectReadableValues(entry, output);
    return;
  }

  if (typeof value === 'object') {
    for (const entry of Object.values(value)) collectReadableValues(entry, output);
  }
}

return parsedItems.map((item, index) => {
  const values = [];
  collectReadableValues(item.json, values);
  const source = sourceItems[index]?.json || {};

  return {
    json: {
      filename: String(source.filename || source.fileName || ''),
      extension: 'xml',
      text: values.join('\n').trim(),
    },
  };
});

return $input.all().map((item, index) => {
  if (!item.binary?.data) {
    throw new Error(`DOCX item ${index + 1} has no binary field named data`);
  }

  const originalFilename = String(
    item.json.filename || item.json.fileName || item.binary.data.fileName || ''
  );

  return {
    json: { ...item.json, filename: originalFilename, extension: 'docx' },
    binary: {
      ...item.binary,
      data: {
        ...item.binary.data,
        fileExtension: 'zip',
        mimeType: 'application/zip',
      },
    },
    pairedItem: { item: index },
  };
});

return $input.all().map((item, index) => {
  const documentXml = Object.entries(item.binary || {}).find(([, data]) => {
    const path = String(data.fileName || '').replace(/\\/g, '/').toLowerCase();
    return path === 'word/document.xml';
  });

  if (!documentXml) {
    throw new Error(
      `word/document.xml was not found inside ${item.json.filename || `DOCX item ${index + 1}`}`
    );
  }

  return {
    json: { ...item.json, extension: 'docx' },
    binary: { data: documentXml[1] },
    pairedItem: { item: index },
  };
});

const parsedItems = $input.all();
const sourceItems = $('Extract DOCX XML to Text').all();

function decodeXmlEntities(value) {
  return value
    .replace(/&#x([0-9a-f]+);/gi, (match, hex) => {
      const code = parseInt(hex, 16);
      return Number.isInteger(code) && code >= 0 && code <= 0x10FFFF
        ? String.fromCodePoint(code)
        : match;
    })
    .replace(/&#(\d+);/g, (match, decimal) => {
      const code = parseInt(decimal, 10);
      return Number.isInteger(code) && code >= 0 && code <= 0x10FFFF
        ? String.fromCodePoint(code)
        : match;
    })
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&amp;/g, '&');
}

function docxXmlToText(xml) {
  let text = String(xml || '');

  text = text
    .replace(/<w:tab\b[^>]*\/>/gi, '\t')
    .replace(/<w:(?:br|cr)\b[^>]*\/>/gi, '\n')
    .replace(/<\/w:tc\s*>/gi, '\t')
    .replace(/<\/w:tr\s*>/gi, '\n')
    .replace(/<\/w:p\s*>/gi, '\n')
    .replace(/<[^>]+>/g, '');

  text = decodeXmlEntities(text);

  return text
    .replace(/\r/g, '')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n[ \t]+/g, '\n')
    .replace(/[ \t]{2,}/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

return parsedItems.map((item, index) => {
  const source = sourceItems[index]?.json || {};

  return {
    json: {
      filename: String(source.filename || source.fileName || ''),
      extension: 'docx',
      text: docxXmlToText(source.xmlContent),
    },
  };
});
